/**
 * The "Quick add" home screen widget (§26) is generated by Expo config plugins
 * because the app is managed (CNG): `ios/` and `android/` are not committed, so
 * the WidgetKit target and the Android AppWidgetProvider must be written by
 * `expo prebuild`. The native code itself can only be verified on a device or
 * simulator; these tests pin what prebuild is asked to produce.
 *
 * The iOS test mutates a small pbxproj fixture with the real plugin and writes
 * it back through the `xcode` writer, so the assertions are made against the
 * file the plugin actually emits, not a mock of it.
 */
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

// `xcode` (used only to parse and write the pbxproj fixture) requires uuid,
// whose browser ESM build is outside jest-expo's transform allowlist. The mock
// keeps the real library and just supplies ids.
jest.mock('uuid', () => ({ v4: () => require('node:crypto').randomUUID() }));

// `xcode` is @expo/config-plugins' own dependency (the plugin under test never
// requires it directly), so resolve it from there rather than assuming hoisting.
const xcode = require(
  require.resolve('xcode', { paths: [path.dirname(require.resolve('@expo/config-plugins'))] }),
);

const plugin = require('./withQuickAddWidget');

const {
  ACCENT_COLOR,
  ANDROID_PROVIDER_CLASS,
  DEEP_LINK_PATH,
  IOS_WIDGET_NAME,
  WIDGET_LABEL,
  getDeepLink,
} = plugin;

const PBXPROJ_FIXTURE = `// !$*UTF8*$!
{
	archiveVersion = 1;
	classes = {
	};
	objectVersion = 54;
	objects = {

/* Begin PBXBuildFile section */
		D0E000000000000000000B01 /* AppDelegate.swift in Sources */ = {isa = PBXBuildFile; fileRef = D0E000000000000000000F02 /* AppDelegate.swift */; };
/* End PBXBuildFile section */

/* Begin PBXFileReference section */
		D0E000000000000000000F01 /* Demo.app */ = {isa = PBXFileReference; explicitFileType = wrapper.application; includeInIndex = 0; path = Demo.app; sourceTree = BUILT_PRODUCTS_DIR; };
		D0E000000000000000000F02 /* AppDelegate.swift */ = {isa = PBXFileReference; lastKnownFileType = sourcecode.swift; name = AppDelegate.swift; path = Demo/AppDelegate.swift; sourceTree = "<group>"; };
		D0E000000000000000000F03 /* Info.plist */ = {isa = PBXFileReference; lastKnownFileType = text.plist.xml; name = Info.plist; path = Demo/Info.plist; sourceTree = "<group>"; };
/* End PBXFileReference section */

/* Begin PBXFrameworksBuildPhase section */
		D0E000000000000000000A01 /* Frameworks */ = {
			isa = PBXFrameworksBuildPhase;
			buildActionMask = 2147483647;
			files = (
			);
			runOnlyForDeploymentPostprocessing = 0;
		};
/* End PBXFrameworksBuildPhase section */

/* Begin PBXGroup section */
		D0E000000000000000000E01 = {
			isa = PBXGroup;
			children = (
				D0E000000000000000000E02 /* Demo */,
				D0E000000000000000000E03 /* Products */,
			);
			sourceTree = "<group>";
		};
		D0E000000000000000000E02 /* Demo */ = {
			isa = PBXGroup;
			children = (
				D0E000000000000000000F02 /* AppDelegate.swift */,
				D0E000000000000000000F03 /* Info.plist */,
			);
			name = Demo;
			path = Demo;
			sourceTree = "<group>";
		};
		D0E000000000000000000E03 /* Products */ = {
			isa = PBXGroup;
			children = (
				D0E000000000000000000F01 /* Demo.app */,
			);
			name = Products;
			sourceTree = "<group>";
		};
/* End PBXGroup section */

/* Begin PBXNativeTarget section */
		D0E000000000000000000D01 /* Demo */ = {
			isa = PBXNativeTarget;
			buildConfigurationList = D0E000000000000000000C01 /* Build configuration list for PBXNativeTarget "Demo" */;
			buildPhases = (
				D0E000000000000000000A02 /* Sources */,
				D0E000000000000000000A01 /* Frameworks */,
				D0E000000000000000000A03 /* Resources */,
				D0E000000000000000000A04 /* Bundle React Native code and images */,
			);
			buildRules = (
			);
			dependencies = (
			);
			name = Demo;
			productName = Demo;
			productReference = D0E000000000000000000F01 /* Demo.app */;
			productType = "com.apple.product-type.application";
		};
/* End PBXNativeTarget section */

/* Begin PBXProject section */
		D0E0000000000000000000901 /* Project object */ = {
			isa = PBXProject;
			attributes = {
				LastUpgradeCheck = 1130;
			};
			buildConfigurationList = D0E000000000000000000C02 /* Build configuration list for PBXProject "Demo" */;
			compatibilityVersion = "Xcode 3.2";
			developmentRegion = en;
			hasScannedForEncodings = 0;
			knownRegions = (
				en,
				Base,
			);
			mainGroup = D0E000000000000000000E01;
			productRefGroup = D0E000000000000000000E03 /* Products */;
			projectDirPath = "";
			projectRoot = "";
			targets = (
				D0E000000000000000000D01 /* Demo */,
			);
		};
/* End PBXProject section */

/* Begin PBXResourcesBuildPhase section */
		D0E000000000000000000A03 /* Resources */ = {
			isa = PBXResourcesBuildPhase;
			buildActionMask = 2147483647;
			files = (
			);
			runOnlyForDeploymentPostprocessing = 0;
		};
/* End PBXResourcesBuildPhase section */

/* Begin PBXShellScriptBuildPhase section */
		D0E000000000000000000A04 /* Bundle React Native code and images */ = {
			isa = PBXShellScriptBuildPhase;
			buildActionMask = 2147483647;
			files = (
			);
			inputPaths = (
			);
			name = "Bundle React Native code and images";
			outputPaths = (
			);
			runOnlyForDeploymentPostprocessing = 0;
			shellPath = /bin/sh;
			shellScript = "echo bundle";
		};
/* End PBXShellScriptBuildPhase section */

/* Begin PBXSourcesBuildPhase section */
		D0E000000000000000000A02 /* Sources */ = {
			isa = PBXSourcesBuildPhase;
			buildActionMask = 2147483647;
			files = (
				D0E000000000000000000B01 /* AppDelegate.swift in Sources */,
			);
			runOnlyForDeploymentPostprocessing = 0;
		};
/* End PBXSourcesBuildPhase section */

/* Begin XCBuildConfiguration section */
		D0E000000000000000000B11 /* Debug */ = {
			isa = XCBuildConfiguration;
			buildSettings = {
				INFOPLIST_FILE = Demo/Info.plist;
				IPHONEOS_DEPLOYMENT_TARGET = 15.1;
				PRODUCT_BUNDLE_IDENTIFIER = "com.example.demo";
				PRODUCT_NAME = Demo;
				SWIFT_VERSION = 5.0;
				TARGETED_DEVICE_FAMILY = 1;
			};
			name = Debug;
		};
		D0E000000000000000000B12 /* Release */ = {
			isa = XCBuildConfiguration;
			buildSettings = {
				CURRENT_PROJECT_VERSION = 11600;
				INFOPLIST_FILE = Demo/Info.plist;
				IPHONEOS_DEPLOYMENT_TARGET = 15.1;
				MARKETING_VERSION = 1.16.0;
				PRODUCT_BUNDLE_IDENTIFIER = "com.example.demo";
				PRODUCT_NAME = Demo;
				SWIFT_VERSION = 5.0;
				TARGETED_DEVICE_FAMILY = 1;
			};
			name = Release;
		};
/* End XCBuildConfiguration section */

/* Begin XCConfigurationList section */
		D0E000000000000000000C01 /* Build configuration list for PBXNativeTarget "Demo" */ = {
			isa = XCConfigurationList;
			buildConfigurations = (
				D0E000000000000000000B11 /* Debug */,
				D0E000000000000000000B12 /* Release */,
			);
			defaultConfigurationIsVisible = 0;
			defaultConfigurationName = Release;
		};
		D0E000000000000000000C02 /* Build configuration list for PBXProject "Demo" */ = {
			isa = XCConfigurationList;
			buildConfigurations = (
				D0E000000000000000000B11 /* Debug */,
				D0E000000000000000000B12 /* Release */,
			);
			defaultConfigurationIsVisible = 0;
			defaultConfigurationName = Release;
		};
/* End XCConfigurationList section */
	};
	rootObject = D0E0000000000000000000901 /* Project object */;
}
`;

function baseConfig(overrides = {}) {
  return {
    name: 'CISA Campus Work Tracker',
    slug: 'cisa-campus',
    scheme: ['cisacampus', 'com.cisa.campus'],
    version: '1.16.0',
    ios: { bundleIdentifier: 'com.example.demo', buildNumber: '11600' },
    android: { package: 'com.example.demo' },
    ...overrides,
  };
}

function tempDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'quick-add-widget-'));
}

function writeFixtureProject(dir) {
  const pbxprojPath = path.join(dir, 'project.pbxproj');
  fs.writeFileSync(pbxprojPath, PBXPROJ_FIXTURE);
  const project = xcode.project(pbxprojPath);
  project.parseSync();
  return { project, pbxprojPath };
}

function modRequest(dir, platform) {
  return {
    projectRoot: dir,
    platformProjectRoot: dir,
    platform,
    projectName: 'Demo',
    introspect: false,
  };
}

describe('quick add widget plugin', () => {
  it('builds the quick-add deep link from the first app scheme', () => {
    expect(DEEP_LINK_PATH).toBe('/quick-add');
    expect(getDeepLink(baseConfig())).toBe('cisacampus://quick-add');
    expect(getDeepLink(baseConfig({ scheme: 'cisacampus' }))).toBe('cisacampus://quick-add');
    expect(() => getDeepLink(baseConfig({ scheme: undefined }))).toThrow(/scheme/i);
  });

  it('declares the widget extension for EAS in app.json', () => {
    const appJson = JSON.parse(
      fs.readFileSync(path.join(__dirname, '..', 'app.json'), 'utf8'),
    );
    const eas = appJson.expo.extra.eas;
    // EAS resolves app extension targets from here; without it the extension
    // is built locally but missing from the managed credentials.
    expect(eas.build.experimental.ios.appExtensions).toEqual([
      {
        targetName: IOS_WIDGET_NAME,
        bundleIdentifier: 'com.cisa.campus.QuickAddWidget',
      },
    ]);
    expect(eas.projectId).toBeTruthy();
  });

  it('registers mods for both platforms', () => {
    const config = plugin(baseConfig());
    expect(typeof config.mods.ios.xcodeproj).toBe('function');
    expect(typeof config.mods.ios.dangerous).toBe('function');
    expect(typeof config.mods.android.manifest).toBe('function');
    expect(typeof config.mods.android.dangerous).toBe('function');
  });

  it('adds a WidgetKit extension target to the Xcode project', async () => {
    const dir = tempDir();
    const { project, pbxprojPath } = writeFixtureProject(dir);

    const config = plugin(baseConfig());
    await config.mods.ios.xcodeproj({
      ...config,
      modResults: project,
      modRequest: modRequest(dir, 'ios'),
    });

    fs.writeFileSync(pbxprojPath, project.writeSync());
    const written = fs.readFileSync(pbxprojPath, 'utf8');

    // The plugin's output has to be a project Xcode can read back.
    const reparsed = xcode.project(pbxprojPath);
    expect(() => reparsed.parseSync()).not.toThrow();

    const target = reparsed.pbxTargetByName(IOS_WIDGET_NAME);
    expect(target).toBeDefined();
    expect(target.productType).toContain('com.apple.product-type.app-extension');
    expect(reparsed.pbxTargetByName('Demo')).toBeDefined();

    // Product is embedded into the app bundle's PlugIns directory.
    expect(written).toMatch(/PBXCopyFilesBuildPhase/);
    expect(written).toMatch(/dstSubfolderSpec = 13;/);
    expect(written).toMatch(/Embed Foundation Extensions/);
    expect(written).toMatch(/RemoveHeadersOnCopy/);

    // App target depends on the extension so it is built first.
    expect(written).toMatch(/PBXTargetDependency/);

    // Bundle id hangs off the app's, and the extension-only flags are set.
    expect(written).toContain('PRODUCT_BUNDLE_IDENTIFIER = "com.example.demo.QuickAddWidget";');
    expect(written).toMatch(/APPLICATION_EXTENSION_API_ONLY = YES;/);
    expect(written).toMatch(/SKIP_INSTALL = YES;/);
    expect(written).toMatch(/INFOPLIST_FILE = QuickAddWidget\/Info.plist;/);
    // Version and deployment target are copied from the app target so an upload
    // never sees a mismatched extension build number.
    expect(written).toContain('MARKETING_VERSION = 1.16.0;');
    expect(written).toContain('CURRENT_PROJECT_VERSION = 11600;');
    expect(written).toContain('IPHONEOS_DEPLOYMENT_TARGET = 15.1;');
  });

  it('inserts the embed phase after the app target resources phase', async () => {
    const dir = tempDir();
    const { project, pbxprojPath } = writeFixtureProject(dir);

    const config = plugin(baseConfig());
    await config.mods.ios.xcodeproj({
      ...config,
      modResults: project,
      modRequest: modRequest(dir, 'ios'),
    });
    fs.writeFileSync(pbxprojPath, project.writeSync());

    const reparsed = xcode.project(pbxprojPath);
    reparsed.parseSync();
    const appTarget = reparsed.pbxTargetByName('Demo');
    const resourcesSection = reparsed.hash.project.objects.PBXResourcesBuildPhase;
    const resourcesIndex = appTarget.buildPhases.findIndex(
      (phase) => resourcesSection[phase.value],
    );

    expect(resourcesIndex).toBeGreaterThanOrEqual(0);
    // Xcode 15+ reports a build cycle when the copy phase lands after the app's
    // script phases, so it has to sit directly after Resources.
    expect(appTarget.buildPhases[resourcesIndex + 1].comment).toBe(
      'Embed Foundation Extensions',
    );
    expect(appTarget.buildPhases[resourcesIndex + 2].comment).toBe(
      'Bundle React Native code and images',
    );
  });

  it('records PBXProject TargetAttributes for the extension target', async () => {
    const dir = tempDir();
    const { project, pbxprojPath } = writeFixtureProject(dir);

    const config = plugin(baseConfig());
    await config.mods.ios.xcodeproj({
      ...config,
      modResults: project,
      modRequest: modRequest(dir, 'ios'),
    });
    fs.writeFileSync(pbxprojPath, project.writeSync());

    const reparsed = xcode.project(pbxprojPath);
    reparsed.parseSync();
    const projectSection = reparsed.hash.project.objects.PBXProject;
    const projectObject = projectSection[reparsed.hash.project.rootObject];
    const targets = reparsed.hash.project.objects.PBXNativeTarget;
    const widgetUuid = Object.keys(targets).find(
      (key) => !key.endsWith('_comment') && targets[key].name === IOS_WIDGET_NAME,
    );

    // No TargetAttributes on the fixture's app target, so the default applies.
    expect(projectObject.attributes.TargetAttributes[widgetUuid]).toEqual({
      CreatedOnToolsVersion: '15.0',
    });
  });

  it('copies the app target CreatedOnToolsVersion when the project has one', async () => {
    const dir = tempDir();
    const pbxprojPath = path.join(dir, 'project.pbxproj');
    fs.writeFileSync(
      pbxprojPath,
      PBXPROJ_FIXTURE.replace(
        'LastUpgradeCheck = 1130;',
        `LastUpgradeCheck = 1130;
				TargetAttributes = {
					D0E000000000000000000D01 = {
						CreatedOnToolsVersion = 16.2;
					};
				};`,
      ),
    );
    const project = xcode.project(pbxprojPath);
    project.parseSync();

    const config = plugin(baseConfig());
    await config.mods.ios.xcodeproj({
      ...config,
      modResults: project,
      modRequest: modRequest(dir, 'ios'),
    });
    fs.writeFileSync(pbxprojPath, project.writeSync());

    const reparsed = xcode.project(pbxprojPath);
    reparsed.parseSync();
    const projectSection = reparsed.hash.project.objects.PBXProject;
    const projectObject = projectSection[reparsed.hash.project.rootObject];
    const targets = reparsed.hash.project.objects.PBXNativeTarget;
    const widgetUuid = Object.keys(targets).find(
      (key) => !key.endsWith('_comment') && targets[key].name === IOS_WIDGET_NAME,
    );

    expect(
      projectObject.attributes.TargetAttributes[widgetUuid].CreatedOnToolsVersion,
    ).toBe('16.2');
  });

  it('does not add the iOS target twice', async () => {
    const dir = tempDir();
    const { project, pbxprojPath } = writeFixtureProject(dir);
    const config = plugin(baseConfig());
    const run = async () =>
      config.mods.ios.xcodeproj({
        ...config,
        modResults: project,
        modRequest: modRequest(dir, 'ios'),
      });

    await run();
    await run();
    fs.writeFileSync(pbxprojPath, project.writeSync());

    const reparsed = xcode.project(pbxprojPath);
    reparsed.parseSync();
    const targets = Object.keys(reparsed.pbxNativeTargetSection()).filter(
      (key) => !key.endsWith('_comment'),
    );
    expect(targets).toHaveLength(2);

    const appTarget = reparsed.pbxTargetByName('Demo');
    const embeds = appTarget.buildPhases.filter(
      (phase) => phase.comment === 'Embed Foundation Extensions',
    );
    expect(embeds).toHaveLength(1);
  });

  it('writes the iOS widget sources and Info.plist', async () => {
    const dir = tempDir();
    const iosRoot = path.join(dir, 'ios');
    fs.mkdirSync(iosRoot);

    const config = plugin(baseConfig());
    await config.mods.ios.dangerous({
      ...config,
      modRequest: modRequest(iosRoot, 'ios'),
    });

    const swift = fs.readFileSync(
      path.join(iosRoot, IOS_WIDGET_NAME, `${IOS_WIDGET_NAME}.swift`),
      'utf8',
    );
    expect(swift).toContain('import WidgetKit');
    expect(swift).toContain('.widgetURL(quickAddURL)');
    expect(swift).toContain('URL(string: "cisacampus://quick-add")');
    expect(swift).toContain(`Text("${WIDGET_LABEL}")`);
    expect(swift).toContain('.supportedFamilies([.systemSmall])');
    expect(swift).toContain('containerBackground');

    const plist = fs.readFileSync(
      path.join(iosRoot, IOS_WIDGET_NAME, 'Info.plist'),
      'utf8',
    );
    expect(plist).toContain('com.apple.widgetkit-extension');
    expect(plist).toContain('$(PRODUCT_BUNDLE_IDENTIFIER)');
  });

  it('adds the Android widget receiver to the manifest', () => {
    const manifest = {
      manifest: {
        $: { 'xmlns:android': 'http://schemas.android.com/apk/res/android' },
        application: [{ $: { 'android:name': '.MainApplication' } }],
      },
    };

    plugin.addAndroidWidgetReceiver(manifest, {
      providerClass: ANDROID_PROVIDER_CLASS,
      label: WIDGET_LABEL,
    });

    const application = manifest.manifest.application[0];
    expect(application.receiver).toHaveLength(1);
    const receiver = application.receiver[0];
    expect(receiver.$['android:name']).toBe(`.${ANDROID_PROVIDER_CLASS}`);
    expect(receiver.$['android:exported']).toBe('false');
    expect(receiver.$['android:label']).toBe(`@string/${'quick_add_widget_label'}`);
    expect(receiver['intent-filter'][0].action[0].$['android:name']).toBe(
      'android.appwidget.action.APPWIDGET_UPDATE',
    );
    expect(receiver['meta-data'][0].$['android:name']).toBe('android.appwidget.provider');
    expect(receiver['meta-data'][0].$['android:resource']).toBe('@xml/quick_add_widget_info');
  });

  it('writes the Android widget provider, layout and resources', async () => {
    const dir = tempDir();

    const config = plugin(baseConfig());
    await config.mods.android.dangerous({
      ...config,
      modRequest: modRequest(dir, 'android'),
    });

    const written = [
      'app/src/main/java/com/example/demo/QuickAddWidgetProvider.kt',
      'app/src/main/res/layout/quick_add_widget.xml',
      'app/src/main/res/xml/quick_add_widget_info.xml',
      'app/src/main/res/drawable/quick_add_widget_background.xml',
      'app/src/main/res/values/quick_add_widget_strings.xml',
    ];
    for (const relative of written) {
      expect(fs.existsSync(path.join(dir, relative))).toBe(true);
    }

    const provider = fs.readFileSync(
      path.join(dir, 'app/src/main/java/com/example/demo/QuickAddWidgetProvider.kt'),
      'utf8',
    );
    expect(provider).toContain('package com.example.demo');
    expect(provider).toContain(`class ${ANDROID_PROVIDER_CLASS} : AppWidgetProvider()`);
    expect(provider).toContain('cisacampus://quick-add');
    expect(provider).toContain('PendingIntent.getActivity');
    expect(provider).toContain('R.layout.quick_add_widget');

    const layout = fs.readFileSync(
      path.join(dir, 'app/src/main/res/layout/quick_add_widget.xml'),
      'utf8',
    );
    expect(layout).toContain('@string/quick_add_widget_label');

    const info = fs.readFileSync(
      path.join(dir, 'app/src/main/res/xml/quick_add_widget_info.xml'),
      'utf8',
    );
    expect(info).toContain('@layout/quick_add_widget');
    expect(info).toContain('android:previewLayout="@layout/quick_add_widget"');
    expect(info).toContain('android:description="@string/quick_add_widget_description"');
    expect(info).toContain('android:targetCellWidth="2"');
    expect(info).toContain('android:targetCellHeight="1"');

    const strings = fs.readFileSync(
      path.join(dir, 'app/src/main/res/values/quick_add_widget_strings.xml'),
      'utf8',
    );
    expect(strings).toContain(
      '<string name="quick_add_widget_description">Open Quick add.</string>',
    );

    const background = fs.readFileSync(
      path.join(dir, 'app/src/main/res/drawable/quick_add_widget_background.xml'),
      'utf8',
    );
    expect(background).toContain(ACCENT_COLOR);
  });
});
